\label{conj:three}
  Let $Q$ be a quiver without oriented cycles. Fix a dimension vector $\beta$, and a weight $\sigma\in\Sigma(Q,\beta)$. If $\dim_{\mathbb{K}}\operatorname{SI}(Q,\beta)_{\sigma}=3$, then $\dim_{\mathbb{K}}\operatorname{SI}(Q,\beta)_{M\sigma}=2M+1$ or
  $\binom{M+2}{2}$ for all positive integers $M$.

\label{thm:thmC}
    Let $k\ge2$, $n\ge k+2$, $d\ge1$, and let $\mathbf a$ be a nondegenerate content for $(k,n,d)$, i.e.\ $\sum_ia_i=kd$ and $1\le a_i\le d-1$ for all $i$. We obtain the following bounds on the weight spaces determined by the nondegenerate content $\mathbf a$
    \[
        \dim_{\mathbb{K}}\operatorname{SI}^{\,\operatorname{Gr}(k,n)}_{(d;\mathbf a)}\ =\ K_{(d^k),\,\mathbf a}\ \ge\
        \begin{cases}
            n-2,&(k,n)=(2,n)\\[1mm]
            3,&(k,n)=(3,5)\\[1mm]
            4,&\text{otherwise}
        \end{cases}
    \]

\label{prop:stability}
    Let $k\ge 2$.
    {\renewcommand{(\alph{enumi})}{(\alph{enumi})} 
     \renewcommand{(\roman{enumii})}{(\roman{enumii})} 
    \begin{enumerate}
      \item Any weight $\sigma\in\Sigma(Q,\beta)$ is of the form
            $\sigma=(-d,a_1,a_2,\dotsc,a_n)$ where $d,a_i\in\mathbb{N}$ with $\sum_ia_i=kd$ and $a_i\leq d$
      \item For such a weight $\sigma\in\Sigma(Q,\beta)$, the dimension vector $\beta$ is
            \begin{enumerate}
              \item $\sigma$-semistable if and only if $0\le a_i\le d$ for all $i$
              \item $\sigma$-stable if and only if $1\le a_i\le d-1$ for all $i$ (assume $d\geq 2$).
            \end{enumerate}
    \end{enumerate}}

For calculating $\dim_{\mathbb{K}}\operatorname{SI}(Q,\beta)_{\sigma}$ we will use the description from \cite[Section 10.4]{DerkWeyBook}. Let $V$ be a representation of $Q$ with $\underline{\dim}V=\beta$. Now $\dim_{\mathbb{K}}\operatorname{SI}(Q,\beta)_{\sigma}$ is the multiplicity of
    \begin{align*}
      &\mathbb{S}_{((-d)^k)}V(0)\otimes\mathbb{S}_{((a_1)^1)}V(1)\otimes\mathbb{S}_{((a_2)^1)}V(2)
       \otimes\dotsb\otimes\mathbb{S}_{((a_n)^1)}V(n)\\
      &\qquad\cong\mathbb{S}_{((d)^k)}V(0)^{*}\otimes\mathbb{S}_{((a_1)^1)}V(1)\otimes\mathbb{S}_{((a_2)^1)}V(2)
       \otimes\dotsb\otimes\mathbb{S}_{((a_n)^1)}V(n)
    \end{align*}
    in
    \begin{align*}
      \mathbb{K}[\operatorname{\mathrm{rep}}_{\beta}(Q)]
      &= \bigoplus_{\substack{\lambda^{(1)},\dotsc,\lambda^{(n)}\\ \text{partitions}}}\;
         \bigotimes_{i=1}^{n}
         \Bigl(\mathbb{S}_{\lambda^{(i)}}V(i)\otimes\mathbb{S}_{\lambda^{(i)}}V(0)^{*}\Bigr)\\
      &\cong \bigoplus_{\substack{\lambda^{(1)},\,\dotsc\,,\lambda^{(n)}\\ \text{partitions}}}
         \Bigl(\,\bigotimes_{i=1}^{n}\mathbb{S}_{\lambda^{(i)}}V(i)\Bigr)
         \otimes
         \Bigl(\,\bigotimes_{i=1}^{n}\mathbb{S}_{\lambda^{(i)}}V(0)^{*}\Bigr)
    \end{align*}
    Therefore, we get that $\lambda^{(i)}=(a_i)^1$ for every $1\leq i\leq n$. Hence, we are looking for the multiplicity of
    \[
        \mathbb{S}_{((d)^k)}V(0)^{*}
    \]
    in
    \[
        \bigotimes_{i=1}^{n}\mathbb{S}_{(a_{i})}V(0)^{*}
    \]
    Hence, we conclude that
    \[
        \dim_{\mathbb{K}}\operatorname{SI}(Q,\beta)_{\sigma}\ =\ K_{(d^k),\,\mathbf a}
    \]

We have two consequences of Proposition~\ref{prop:dimformula} that we will use throughout.
    \begin{enumerate}
        \item The term \emph{content} has been used in two ways: for weights of the subspace quiver, see Definition~\ref{def:content}, and for tableaux, see Definition~\ref{def:ssyt}. We note that both the notions agree. Indeed, by Proposition~\ref{prop:stability} and Proposition~\ref{prop:dimformula}, a sequence $\mathbf a$ is a content for $(k,n,d)$ if and only if $K_{(d^k),\,\mathbf a}\neq0$, i.e., if and only if $\mathbf a$ is the content of some semistandard tableau of shape $(d^k)$.
        \item We will often write $\operatorname{SI}^{\,\operatorname{Gr}(k,n)}_{(d;\mathbf a)}$ for the weight space $\operatorname{SI}(Q,\beta)_{\sigma}$ with $\sigma=(-d,a_1,\dots,a_n)$ and use them interchangeably. We drop the superscript when $(k,n)$ is clear from the context.
    \end{enumerate}

\label{lem:T2}
    Let $\mathbf a$ be a content for $(k,n,d)$. Define $\mathbf a^\vee:=(d-a_1,\dots,d-a_n)$. For every integer $m\ge1$, we have
    \[
        \dim_{\mathbb{K}}\operatorname{SI}_{(md;m\mathbf a)}^{\,\operatorname{Gr}(k,n)}\ =\ \dim_{\mathbb{K}}\operatorname{SI}_{(md;m\mathbf a^\vee)}^{\,\operatorname{Gr}(n-k,n)}
    \]
    In terms of Kostka coefficients we get
    \[
        K_{(d^k),\,\mathbf a}\ =\ K_{(d^{\,n-k}),\,\mathbf a^{\vee}}
    \]
    Moreover, $\mathbf a$ is nondegenerate if and only if $\mathbf a^\vee$ is.

\label{lem:T3}
    Suppose $\mathbf a$ is a content for $(k,n,d)$ with $a_i=d$ for some $i$. Let $\mathbf a'$ be
    obtained by deleting the $i$-th entry. For every integer $m\ge1$, we have
    \[
        \dim_{\mathbb{K}}\operatorname{SI}_{(md;m\mathbf a)}^{\,\operatorname{Gr}(k,n)}\ =\ \dim_{\mathbb{K}}\operatorname{SI}_{(md;m\mathbf a')}^{\,\operatorname{Gr}(k-1,n-1)}
    \]
    Combinatorially, we get
    \[
        K_{(d^k),\,\mathbf a}\ =\ K_{(d^{\,k-1}),\,\mathbf a'}
    \]

\label{lem:interlace}
    Let $\mu\subseteq\lambda$ be partitions. The skew diagram $\lambda/\mu$ is a horizontal strip if and only if
    \begin{equation}
    \label{eq:interlace}
        \lambda_1\ \ge\ \mu_1\ \ge\ \lambda_2\ \ge\ \mu_2\ \ge\ \lambda_3\ \ge\ \mu_3\ \ge\ \cdots
    \end{equation}

\label{lem:striporder}
    Let $\lambda/\mu$ be a horizontal strip. If $(i,j)$ and $(i',j')$ are cells of $\lambda/\mu$ with
    $i<i'$, then $j'<j$. In particular, cells in the lower rows of a horizontal strip occupy strictly smaller columns.

\label{prop:T1image}
    Let $\lambda=(d^k)$ be a rectangle, and
    $\mathbf a=(a_1,\dots,a_{\ell-1},p,q)$ be a content with $\ell$ and $\ell+1$ as the two largest letters. In such a case, the injection $\Phi$ of Lemma~\ref{lem:polarization} is a bijection. More precisely,
    \[
        \Phi:\ \operatorname{SSYT}\bigl((d^k),\mathbf a^{\,\mathrm{mrg}}\bigr)\ \xrightarrow{\ \sim\ }\
        \bigl\{T\in\operatorname{SSYT}\bigl((d^k),\mathbf a\bigr)\ :\ \text{no column of $T$ contains both $\ell$ and $\ell+1$}\bigr\}.
    \]
    In particular,
    \begin{equation}
    \label{eq:strict}
        K_{(d^k),\,\mathbf a}\ =\ K_{(d^k),\,\mathbf a^{\,\mathrm{mrg}}}\ +\
        \#\bigl\{T\in\operatorname{SSYT}((d^k),\mathbf a):\ \text{some column contains both $\ell$ and $\ell+1$}\bigr\}.
    \end{equation}

\label{lem:CG}
    For $a,b\ge0$,
    \[
        V_a\otimes V_b\ \cong\ \bigoplus_{t=0}^{\min(a,b)} V_{a+b-2t}
        \qquad\text{as }\mathrm{SL}_2\text{-representations}
    \]

\label{prop:fusion}
    For $n\ge3$,
    \begin{equation}
    \label{eq:fusrecur}
        F(a_1,\dots,a_n)\ =\ \sum_{t=0}^{\min(a_{n-1},a_n)} F\bigl(a_1,\dots,a_{n-2},\,j_t\bigr),
        \qquad j_t:=a_{n-1}+a_n-2t .
    \end{equation}
    The $t$-th summand is a content in $n-1$ letters whose half-sum is $d-t$.

\label{thm:star}
    Let $k\ge2$, $n\ge k+2$, $d\ge1$, and let $\mathbf a$ be a nondegenerate content for $(k,n,d)$, i.e.\ $\sum_ia_i=kd$ and $1\le a_i\le d-1$ for all $i$. We obtain the following bounds on the weight spaces determined by the nondegenerate content $\mathbf a$
    \[
        \dim_{\mathbb{K}}\operatorname{SI}^{\,\operatorname{Gr}(k,n)}_{(d;\mathbf a)}\ =\ K_{(d^k),\,\mathbf a}\ \ge\
        \begin{cases}
            2,&(k,n)=(2,4),\\[1mm]
            3,&(k,n)\in\{(2,5),\,(3,5)\},\\[1mm]
            4,&\text{otherwise}
        \end{cases}
    \]

\label{lem:coords}
    The assignment $T\mapsto(X_1,\dots,X_4)$ is a bijection from the set of such
    tableaux onto the set of integer vectors satisfying
    \begin{equation}\label{eq:cons}
        X_5=d,\qquad 0\le X_j-X_{j-1}\le a_j\ \ (1\le j\le 5),\qquad X_{j-1}+X_j\ \ge\ A_j\ \ (1\le j\le5).
    \end{equation}
